import { Asset } from 'expo-asset';
import { File } from 'expo-file-system';

import { parseGpx } from '@/features/export/lib/gpx';
import { type Fix } from '@/features/tracking/lib/types';

/**
 * The GPX the "Simulate run" button replays: a fictional 5 km out-and-back
 * along Crissy Field, generated by the demo route generator (with GPS noise
 * and two multipath spikes) and bundled as a plain asset so it goes through
 * the same parser as a user's import.
 */
// eslint-disable-next-line @typescript-eslint/no-require-imports
const SIMULATED_RUN = require('../../../../assets/routes/crissy-field-5k.gpx');

export async function loadSimulatedRun(): Promise<Fix[]> {
  const asset = Asset.fromModule(SIMULATED_RUN);
  await asset.downloadAsync();
  const text = await new File(asset.localUri ?? asset.uri).text();
  return parseGpx(text).segments.flat();
}
